#include <bits/stdc++.h>
using namespace std;

int main() {
    ifstream fin("/workdir/data/parking.txt");
    int n, m;
    fin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; i++) fin >> grid[i];

    // Compute heights: height[i][j] = consecutive empty cells ending at row i, column j (going upward)
    vector<vector<int>> height(n, vector<int>(m, 0));
    for (int j = 0; j < m; j++) {
        for (int i = 0; i < n; i++) {
            if (grid[i][j] == '.') height[i][j] = (i > 0 ? height[i-1][j] : 0) + 1;
            else height[i][j] = 0;
        }
    }

    // answer[h][w] for h from 1 to n, w from 1 to m
    // Using long long for counts
    vector<vector<long long>> ans(n+1, vector<long long>(m+1, 0));

    // Second-order difference array
    vector<long long> S(m+5);

    for (int h = 1; h <= n; h++) {
        fill(S.begin(), S.end(), 0);
        for (int r = 0; r < n; r++) {
            int run_len = 0;
            for (int c = 0; c < m; c++) {
                if (height[r][c] >= h) {
                    run_len++;
                } else {
                    if (run_len > 0) {
                        S[1] += run_len;
                        S[2] -= (long long)(run_len + 1);
                        S[run_len + 2] += 1;
                        run_len = 0;
                    }
                }
            }
            if (run_len > 0) {
                S[1] += run_len;
                S[2] -= (long long)(run_len + 1);
                S[run_len + 2] += 1;
            }
        }
        // Compute prefix sums twice to get answer[h][w]
        for (int w = 1; w <= m; w++) {
            S[w] += S[w-1]; // first prefix sum -> first-order diff D
        }
        long long cumsum = 0;
        for (int w = 1; w <= m; w++) {
            cumsum += S[w]; // second prefix sum -> answer
            ans[h][w] = cumsum;
        }
    }

    ofstream fout("/workdir/answer.txt");
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (j > 1) fout << " ";
            fout << ans[i][j];
        }
        fout << "\n";
    }
    return 0;
}
